const aliases={name:['supplier','supplier name','vendor','vendor name','供应商','供应商名称'],reference:['reference','quote reference','quotation number','报价编号'],product:['product','product name','item','item name','description','产品','产品名称','品名','商品名称'],sku:['sku','item code','product code','part number','material code','产品编码','物料编码','货号'],specification:['specification','specifications','spec','model','规格','型号','规格型号'],unit:['unit','uom','units of measure','单位'],qty:['quantity','qty','数量','采购数量'],price:['unit price','price','unit cost','单价'],moq:['moq','minimum quantity','最小起订量'],shipping:['shipping','shipping fee','freight','运费'],fees:['fees','other fees','其他费用'],days:['delivery days','delivery time','lead time','交货天数','交期','交货期'],discount:['discount','discount %','discount percent','折扣','折扣率'],discountType:['discount type','折扣类型'],tax:['tax','tax rate','tax %','vat','税率'],taxShipping:['tax shipping','shipping taxable','运费计税'],taxFees:['tax fees','fees taxable','其他费用计税'],paymentDays:['payment days','payment terms days','付款期限'],allowSplit:['allow split','partial orders','允许拆单'],taxIncluded:['tax included','含税'],currency:['currency','币种'],validUntil:['valid until','expiry date','有效期'],prepay:['prepayment %','deposit %','预付款比例'],minOrder:['minimum order value','起订金额'],reliability:['reliability','reliability score','可靠性'],evidence:['evidence','reliability evidence','可靠性依据']};
