function migrate(v){if(v?.version===2)return validateWorkspace(v);if(v?.version!==1||!Array.isArray(v.quotes)||!Array.isArray(v.basket))throw Error('Not a supported QuotePilot backup');const p={...projectDefaults(),name:v.project,currency:v.currency,deadline:v.deadline??'',weights:v.weights||{cost:70,delivery:30,reliability:0},sample:!!v.sample,basket:v.basket.map(x=>({...x,unit:''})),quotes:v.quotes.map(q=>({...quoteDefaults(q.currency),...q,reviewed:false,source:'Imported from QuotePilot v1 — review required',items:q.items.map(x=>({...x,unit:'',moq:0}))}))};validateProject(p);return {...workspace(),activeId:p.id,projects:[p]};}
function validateWorkspace(w){for(const k of Object.keys(w||{}))if(!['version','activeId','projects','preferences','api','updatedAt'].includes(k))delete w[k];if(w?.version!==2||!Array.isArray(w.projects)||w.projects.length>100)throw Error('Invalid workspace (maximum 100 projects)');const ids=new Set();w.projects.forEach(p=>{validateProject(p);if(ids.has(p.id))throw Error('Duplicate project ID');ids.add(p.id);});if(w.activeId&&!ids.has(w.activeId))w.activeId=w.projects[0]?.id||'';w.preferences={language:w.preferences?.language==='zh'?'zh':'en'};const api=w.api||{};w.api={endpoint:typeof api.endpoint==='string'?api.endpoint:'https://api.openai.com/v1/chat/completions',protocol:api.protocol==='responses'?'responses':'chat',model:typeof api.model==='string'?api.model:'',timeout:Number.isInteger(api.timeout)&&api.timeout>=5&&api.timeout<=120?api.timeout:60};for(const p of w.projects){p.activity=Array.isArray(p.activity)?p.activity.filter(x=>x&&typeof x.action==='string'&&typeof x.at==='string').slice(0,100):[];if(p.decision&&(!p.decision.bundle||typeof p.decision.supplierName!=='string'||!Number.isFinite(p.decision.total)||!(Object.hasOwn(CURRENCIES,p.decision.currency))||typeof p.decision.reason!=='string'))throw Error('Invalid decision snapshot');if(p.aiReport&&(!Array.isArray(p.aiReport.bundle?.facts)||!Array.isArray(p.aiReport.bundle?.opportunities)||!Array.isArray(p.aiReport.result?.opportunityIds)||!Array.isArray(p.aiReport.result?.reasonFactIds)))throw Error('Invalid saved AI report');}return w;}
